-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-900a-000000000001'::uuid, '00000000-0000-4000-900a-000000000002'::uuid, '00000000-0000-4000-900a-000000000003'::uuid, '00000000-0000-4000-900a-000000000004'::uuid, '00000000-0000-4000-900a-000000000005'::uuid, '00000000-0000-4000-900a-000000000006'::uuid, '00000000-0000-4000-900a-000000000007'::uuid, '00000000-0000-4000-900a-000000000008'::uuid, '00000000-0000-4000-900a-000000000009'::uuid, '00000000-0000-4000-900a-00000000000a'::uuid, '00000000-0000-4000-900a-00000000000b'::uuid, '00000000-0000-4000-900a-00000000000c'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
